package io.github.baeseungwon1010.officecanvas.pptx

import io.github.baeseungwon1010.officecanvas.slide.*
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import kotlin.math.abs

/**
 * pptx_features.pptx is generated by tools/make_pptx_features.py (python-pptx plus
 * hand-written XML for what python-pptx can't express); each slide exercises one
 * part of the .pptx inheritance and drawing model with values checked exactly here.
 */
class PptxFeatureTest {

    private val deck by lazy {
        PptxParser.parse(File(javaClass.classLoader!!.getResource("pptx_samples/pptx_features.pptx")!!.toURI()))
    }

    private fun shapes(slide: Int) = deck.slides[slide].elements.filterIsInstance<Element.Shape>()
    private fun pictures(slide: Int) = deck.slides[slide].elements.filterIsInstance<Element.Picture>()
    private fun rgb(argb: Int) = Triple((argb shr 16) and 0xFF, (argb shr 8) and 0xFF, argb and 0xFF)

    @Test
    fun `the hidden slide is left out`() {
        assertEquals(8, deck.slides.size)
    }

    @Test
    fun `a shape with no fill of its own takes the theme fill its style points at`() {
        val styled = shapes(0)[0]
        // fillRef idx 3 in the default theme is a gradient of accent1 (4F81BD) shades.
        val g = styled.gradient
        assertNotNull("fill should come from the theme's fill style", g)
        for (c in g!!.colors) { val (r, _, b) = rgb(c); assertTrue("accent1 shades are blue: ${Integer.toHexString(c)}", b > r) }
        // lnRef idx 1: the theme's first line style, accent1 at shade 95% / satMod 105%.
        assertEquals(0xFF4A7EBB.toInt(), styled.strokeArgb)
    }

    @Test
    fun `shadows come from the shape's effect list or its style's theme effect`() {
        // The default style points at the theme's second effect style: 35% black, 23000 EMU down.
        val themed = shapes(0)[0].shadow!!
        assertEquals(0x59, themed.argb ushr 24)
        assertEquals(0L, themed.dxEmu)
        assertEquals(23000L, themed.dyEmu)
        // An explicit shadow: 152400 EMU at 45 degrees, no blur.
        val own = shapes(7)[0].shadow!!
        assertEquals(107763.0, own.dxEmu.toDouble(), 2.0)
        assertEquals(107763.0, own.dyEmu.toDouble(), 2.0)
        assertEquals(0L, own.blurEmu)
        // An empty <a:effectLst> means no effects, whatever the style says.
        assertNull(shapes(7)[1].shadow)
    }

    @Test
    fun `a table with no style id has no style`() {
        val plain = deck.slides[6].elements.filterIsInstance<Element.Table>().single { it.cells.size == 2 && it.cells[0].size == 1 }
        assertTrue(plain.cells.flatten().all { it?.fillArgb == null })
    }

    @Test
    fun `a turned, flipped group turns its members, which take its fill`() {
        val emu = 914400.0
        val member = shapes(7).single { it.geometry == "rect" && it.fillArgb == 0xFFC00000.toInt() }
        // Flipped about the group's center (6.75in, 5in), then turned 90 degrees.
        assertEquals(7.0, (member.box.x + member.box.w / 2) / emu, 0.01)
        assertEquals(5.25, (member.box.y + member.box.h / 2) / emu, 0.01)
        assertEquals(90f, member.rotation, 0.01f)
        assertTrue(member.flipH)
    }

    @Test
    fun `a shape turned in 3-D keeps its camera and extrusion`() {
        val s3 = shapes(7).mapNotNull { it.scene3d }.single()
        assertEquals(60f, s3.lonDeg, 0.01f)
        assertEquals(548640L, s3.depthEmu)
        assertEquals(0xFF0000C0.toInt(), s3.extrusionArgb)
    }

    @Test
    fun `highlighted runs keep their highlight color`() {
        val run = shapes(7).mapNotNull { it.text }.flatMap { it.paragraphs }.flatMap { it.runs }.single { it.text == "highlighted" }
        assertEquals(0xFFFFC000.toInt(), run.highlightArgb)
    }

    @Test
    fun `a run's own outer shadow is kept for its letters`() {
        val runs = shapes(7).mapNotNull { it.text }.flatMap { it.paragraphs }.flatMap { it.runs }
        assertNull(runs.single { it.text == "highlighted" }.shadow)
        // 50800 EMU at 45 degrees, no blur.
        val shadow = runs.single { it.text == " shadowed" }.shadow!!
        assertEquals(0xFF000000.toInt(), shadow.argb)
        assertEquals(35921.0, shadow.dxEmu.toDouble(), 2.0)
        assertEquals(35921.0, shadow.dyEmu.toDouble(), 2.0)
        assertEquals(0L, shadow.blurEmu)
    }

    @Test
    fun `scheme colors take their luminance modifiers`() {
        // accent2 C0504D at lumMod 50% is about #632523.
        val (r, g, b) = rgb(shapes(0)[1].fillArgb!!)
        assertTrue("got $r,$g,$b", abs(r - 0x63) <= 2 && abs(g - 0x25) <= 2 && abs(b - 0x23) <= 2)
    }

    @Test
    fun `background and placeholder position come from the master`() {
        assertEquals(0xFFE8F0E0.toInt(), deck.slides[1].backgroundArgb)
        val title = shapes(1).single { it.text?.paragraphs?.firstOrNull()?.plainText == "Inherited title" }
        assertEquals(Box(457200, 274638, 8229600, 1143000), title.box)
        val run = title.text!!.paragraphs[0].runs[0]
        assertEquals(44f, run.sizePt, 0.01f)
        assertEquals(HAlign.CENTER, title.text!!.paragraphs[0].align)
    }

    @Test
    fun `connectors keep their route and arrowheads`() {
        val (elbow, straight) = shapes(2)
        assertNotNull("an elbow connector is an open outline", elbow.outline)
        assertNull("open outlines are never filled", elbow.fillArgb)
        assertTrue(elbow.tailArrow)
        assertFalse(elbow.headArrow)
        assertEquals(0xFFC00000.toInt(), elbow.strokeArgb)
        assertEquals("line", straight.geometry)
        assertTrue(straight.headArrow)
    }

    @Test
    fun `preset shapes get their real outlines`() {
        val outlines = shapes(3).map { it.outline }
        assertEquals(4, outlines.size)
        outlines.forEach { assertNotNull(it) }
        // A five-point star has ten corners.
        assertEquals(10, outlines[2]!!.count { it is PathOp.MoveTo || it is PathOp.LineTo })
    }

    @Test
    fun `text features`() {
        val texts = shapes(4).mapNotNull { it.text }
        val numbered = texts[0].paragraphs
        // A bulleted paragraph breaks the sequence; numbering starts over after it.
        assertEquals(listOf("1.", "2.", "3.", "•", "1."), numbered.map { it.bullet })
        assertEquals(342900L, numbered[0].marginLeftEmu)
        assertEquals(0L, numbered[0].bulletIndentEmu)

        val sup = texts[1].paragraphs[0].runs
        assertEquals(0f, sup[0].baselinePercent, 0f)
        assertEquals(30f, sup[1].baselinePercent, 0.01f)

        assertFalse("wrap=none", texts[2].wrap)

        val shrunk = texts[3].paragraphs[0]
        assertEquals("fontScale 50% of 40pt", 20f, shrunk.runs[0].sizePt, 0.01f)
        assertEquals("lnSpcReduction 10%", 90f, shrunk.lineSpacingPercent, 0.01f)

        assertEquals("5", texts[4].paragraphs[0].plainText)
    }

    @Test
    fun `pictures - crop, SVG-only icons, alternate content fallback`() {
        val pics = pictures(5)
        assertEquals(3, pics.size)
        assertEquals(0.5f, pics[0].crop!!.left, 0.001f)
        assertTrue(pics[1].imageEntry!!.endsWith(".svg"))
        assertNotNull("the picture inside mc:Fallback is drawn", pics[2].imageEntry)
    }

    @Test
    fun `tables in the default style get its header and band fills`() {
        val table = deck.slides[6].elements.filterIsInstance<Element.Table>().first()
        val header = table.cells[0][0]!!
        assertEquals(0xFF4F81BD.toInt(), header.fillArgb)
        val headerRun = header.text!!.paragraphs[0].runs[0]
        assertTrue(headerRun.bold)
        assertEquals(0xFFFFFFFF.toInt(), headerRun.colorArgb)
        // Banded rows alternate between a 40% and a 20% tint of accent1.
        assertNotEquals(table.cells[1][0]!!.fillArgb, table.cells[2][0]!!.fillArgb)
        assertEquals(0xFFFFFFFF.toInt(), table.gridArgb)
    }
}
